from .syslog_entry import SyslogEntry


class UexgateSyslogEntry(SyslogEntry):
    """
    Log entry in syslog file captured by UExGate UE simulator.
    """

    def __init__(self, uexgate_timestamp, **kwargs):
        super(UexgateSyslogEntry, self).__init__(**kwargs)
        self.uexgate_timestamp = uexgate_timestamp
